$decodeId = static function(string $token): int {
    if ($token === '') return 0;
    if (ctype_digit($token)) return (int)$token;
    $id = decryptId($token);
    return $id === false ? 0 : $id;
};
$tokenId = $decodeId(trim((string)($_GET['id'] ?? '')));
$districtsSql = 'SELECT d.id,d.district_name FROM districts d WHERE ' . activeArchiveExclusion('district', 'd.id');
$districtParams = [];
if ($scope !== null) { $districtsSql .= ' AND d.id=?'; $districtParams[] = $scope; }
$districtsSql .= ' ORDER BY d.district_name';
$districtStmt = $db->prepare($districtsSql);
$districtStmt->execute($districtParams);
$districts = $districtStmt->fetchAll(PDO::FETCH_ASSOC);
$municipalities = $db->query("SELECT id,municipality_name FROM municipalities WHERE province_name='Aurora' ORDER BY municipality_name")->fetchAll(PDO::FETCH_ASSOC);

$levelLabels = ['elementary'=>'Elementary','jhs'=>'Junior High School','shs'=>'Senior High School'];
$badge = static fn(string $value): string => '<span class="badge badge-blue">' . clean(ucwords(str_replace('_', ' ', $value))) . '</span>';
?>
