const level=document.getElementById('applicantLevel'),spec=document.getElementById('applicantSpecialization');
function filterApplicantSpecs(){const selected=level.value;let first='';[...spec.options].forEach((o,i)=>{if(i===0)return;const allowed=o.dataset[selected]==='1';o.hidden=!allowed;o.disabled=!allowed;if(allowed&&!first)first=o.value});if(selected==='elementary'){const general=[...spec.options].find(o=>o.dataset.name==='General Education');if(general)spec.value=general.value}else if(spec.selectedOptions[0]?.disabled)spec.value=''}
level.addEventListener('change',filterApplicantSpecs);filterApplicantSpecs();
function totalScores(){let total=0;document.querySelectorAll('.applicant-score').forEach(i=>{const n=Number(i.value);if(Number.isFinite(n)&&n>=0)total+=n});document.getElementById('applicantTotal').textContent=total.toFixed(2)}document.querySelectorAll('.applicant-score').forEach(i=>i.addEventListener('input',totalScores));totalScores();
</script>
