<script>const rl=document.getElementById('requestLevel'),rs=document.getElementById('requestSpecialization'),school=document.getElementById('requestSchool'),teacher=document.getElementById('requestTeacher');function filterRequestSpecs(){const v=rl.value;[...rs.options].forEach((o,i)=>{if(i===0)return;const ok=o.dataset[v]==='1';o.hidden=!ok;o.disabled=!ok});if(v==='elementary'){const g=[...rs.options].find(o=>o.dataset.name==='General Education');if(g)rs.value=g.value}else if(rs.selectedOptions[0]?.disabled)rs.value=''}function filterTeachers(){[...teacher.options].forEach((o,i)=>{if(i===0)return;o.hidden=o.dataset.school!==school.value;o.disabled=o.hidden});if(teacher.selectedOptions[0]?.disabled)teacher.value='0'}function duration(){const a=new Date(document.getElementById('leaveStart').value+'T00:00:00'),b=new Date(document.getElementById('leaveEnd').value+'T00:00:00');document.getElementById('leaveDuration').textContent=Number.isNaN(a.getTime())||Number.isNaN(b.getTime())?'—':Math.floor((b-a)/86400000)+' days'}rl.addEventListener('change',filterRequestSpecs);school.addEventListener('change',filterTeachers);document.getElementById('leaveStart').addEventListener('change',duration);document.getElementById('leaveEnd').addEventListener('change',duration);filterRequestSpecs();filterTeachers();duration();</script>

