<div class="table-card glass-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Request</th><th>School</th><th>District</th><th>Level / Specialization</th><th>Leave Period</th><th>Slots</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= clean($row['request_code']) ?></td><td><?= clean($row['school_name']) ?></td><td><?= clean($row['district_name']) ?></td><td><?= clean(($levelLabels[$row['level']]??$row['level']).' · '.$row['specialization_name']) ?></td><td><?= clean($row['leave_start_date'].' to '.$row['expected_end_date']) ?></td><td><?= (int)$row['substitutes_needed'] ?></td><td><?= $badge($row['status']) ?></td><td><a class="btn btn-ghost btn-sm" href="<?= APP_URL ?>/applicants.php?view=request&id=<?= urlencode(encryptId((int)$row['id'])) ?>">Open</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="text-center text-muted">No substitute requests.</td></tr><?php endif; ?></tbody></table></div></div>
<?php else:
$activeTab=$tab==='active';$statuses=$activeTab?["scheduled","active"]:["completed","cancelled","ended_early"];$placeholders=implode(',',array_fill(0,count($statuses),'?'));$sql="SELECT sa.*,a.application_code,a.last_name,a.first_name,s.school_name,d.district_name,sr.request_code FROM substitute_assignments sa INNER JOIN teacher_applicants a ON a.id=sa.applicant_id INNER JOIN schools s ON s.id=sa.school_id INNER JOIN districts d ON d.id=s.district_id INNER JOIN substitute_requests sr ON sr.id=sa.substitute_request_id WHERE sa.assignment_status IN ($placeholders)";$params=$statuses;if($scope!==null){$sql.=' AND s.district_id=?';$params[]=$scope;}$sql.=' ORDER BY sa.assigned_at DESC LIMIT 250';$st=$db->prepare($sql);$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC); ?>
<div class="table-card glass-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Request</th><th>Applicant</th><th>School</th><th>Period</th><th>Distance Used</th><th>Status</th><?php if($activeTab&&canManageApplicants()): ?><th>Close Assignment</th><?php endif; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= clean($row['request_code']) ?></td><td><?= clean($row['application_code'].' · '.$row['last_name'].', '.$row['first_name']) ?></td><td><?= clean($row['school_name'].' · '.$row['district_name']) ?></td><td><?= clean($row['start_date'].' to '.$row['expected_end_date']) ?></td><td><?= $row['road_distance_km']!==null?number_format((float)$row['road_distance_km'],2).' km':'Unavailable' ?></td><td><?= $badge($row['assignment_status']) ?></td><?php if($activeTab&&canManageApplicants()): ?><td><form method="POST" action="<?= APP_URL ?>/actions/manage_substitute_assignment.php" style="display:flex;gap:5px"><input type="hidden" name="csrf_token" value="<?= csrfToken() ?>"><input type="hidden" name="action" value="close"><input type="hidden" name="assignment_id" value="<?= (int)$row['id'] ?>"><input type="date" class="form-input" name="actual_end_date" value="<?= date('Y-m-d') ?>" required><select class="form-select" name="status"><option value="completed">Completed</option><option value="cancelled">Cancelled</option><option value="ended_early">Ended Early</option></select><button class="btn btn-primary btn-sm">Save</button></form></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="text-center text-muted">No assignments in this tab.</td></tr><?php endif; ?></tbody></table></div></div>
<?php endif; ?>
<?php endif; ?>

